endpoint.response:
"user_id": int | null,
"user": { "id": int, "name": string } | null
// omessi entrambi se `user_id` non e' visibile per field permission

endpoint.errors:
422 `referents.user_already_linked` se l'utente e' gia' legato a un altro referente (D-10);
422 se l'utente non esiste;
403 senza l'ability di risorsa; 422 con l'ability ma senza field permission EDITABILE.

endpoint.request:
"recipient_type": "referent" | "user" | "registry" | null,   // ORA ACCETTATO (emenda 0089 D-7)
"recipient_id": int | null
// omesso -> derivato dal ruolo, comportamento identico a oggi
